<script setup>
import { Link,useForm,router } from '@inertiajs/vue3';
const props=defineProps({branch:Object,count:Object});
const forms={};
for(const item of props.count.items) forms[item.id]=useForm({counted_qty:item.counted_qty??'',note:item.note??''});
function save(item){forms[item.id].patch(`/admin/branches/${props.branch.id}/inventory/counts/${props.count.id}/items/${item.id}`,{preserveScroll:true});}
function post(){if(confirm('سيتم ترحيل الجرد وتسجيل فروق المخزون. هل تريد المتابعة؟'))router.post(`/admin/branches/${props.branch.id}/inventory/counts/${props.count.id}/post`,{}, {preserveScroll:true});}
const qty=(v)=>Number(v||0).toLocaleString('ar-EG',{maximumFractionDigits:3});
</script>
<template><main dir="rtl" class="mx-auto max-w-6xl space-y-6 p-4 sm:p-6"><header><Link :href="`/admin/branches/${branch.id}/inventory/counts`" class="text-sm font-bold text-amber-700">عمليات الجرد</Link><h1 class="mt-1 text-3xl font-black">جرد #{{count.id}}</h1><p class="mt-1 text-sm text-slate-500">الحالة: {{count.status==='draft'?'مسودة':count.status==='posted'?'تم الترحيل':'ملغي'}}</p></header><section class="overflow-hidden rounded-2xl border bg-white"><div v-for="item in count.items" :key="item.id" class="grid gap-3 border-b p-4 sm:grid-cols-4 sm:items-end"><div><p class="font-bold">{{item.ingredient?.name}}</p><p class="mt-1 text-xs text-slate-500">الرصيد المتوقع وقت الترحيل يتحدث إلى الرصيد الفعلي الحالي. المسجل عند بدء الجرد: {{qty(item.expected_qty)}} {{item.ingredient?.base_unit?.symbol}}</p></div><label class="text-sm">الكمية الفعلية<input v-model="forms[item.id].counted_qty" :disabled="count.status!=='draft'" type="number" min="0" step="0.001" class="mt-1 w-full rounded-lg border-slate-300"/></label><label class="text-sm">ملاحظة<input v-model="forms[item.id].note" :disabled="count.status!=='draft'" class="mt-1 w-full rounded-lg border-slate-300"/></label><button v-if="count.status==='draft'" @click="save(item)" class="rounded-lg border px-4 py-2 text-sm font-bold">حفظ الكمية</button><div v-else class="text-sm font-bold">الفرق: {{qty(item.variance_qty)}}</div></div></section><button v-if="count.status==='draft'" @click="post" class="rounded-xl bg-emerald-700 px-6 py-3 font-bold text-white">ترحيل الجرد وتسجيل الفروق</button></main></template>
